import{_ as e,c as r,o as i,af as h}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"第四卦 蒙 山水蒙 艮上坎下","description":"周易 - 第四卦 蒙 山水蒙 艮上坎下","frontmatter":{"title":"第四卦 蒙 山水蒙 艮上坎下","description":"周易 - 第四卦 蒙 山水蒙 艮上坎下"},"headers":[],"relativePath":"classics/zhouyi/005.md","filePath":"classics/zhouyi/005.md"}'),l={name:"classics/zhouyi/005.md"};function t(n,a,s,d,o,c){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="蒙" tabindex="-1">蒙 <a class="header-anchor" href="#蒙" aria-label="Permalink to “蒙”">​</a></h1><h2 id="卦辭" tabindex="-1">卦辭 <a class="header-anchor" href="#卦辭" aria-label="Permalink to “卦辭”">​</a></h2><p>亨。匪我求童蒙，童蒙求我。初噬告，再三瀆，瀆則不告。利貞。</p><h3 id="彖傳" tabindex="-1">彖傳 <a class="header-anchor" href="#彖傳" aria-label="Permalink to “彖傳”">​</a></h3><p>蒙，山下有險，險而止，蒙。蒙亨，以亨行時中也。匪我求童蒙，童蒙求我，志應也。初噬告，以剛中也。再三瀆，瀆則不告，瀆蒙也。蒙以養正，聖功也。</p><h3 id="象傳" tabindex="-1">象傳 <a class="header-anchor" href="#象傳" aria-label="Permalink to “象傳”">​</a></h3><p>山下出 泉，蒙；君子以果行育德。</p><h3 id="初六" tabindex="-1">初六 <a class="header-anchor" href="#初六" aria-label="Permalink to “初六”">​</a></h3><p>發矇，利用刑人，用說桎梏，以往吝。象曰：利用刑人，以正法也。</p><h3 id="九二" tabindex="-1">九二 <a class="header-anchor" href="#九二" aria-label="Permalink to “九二”">​</a></h3><p>包蒙吉；納婦吉；子克家。象曰：子克家，剛柔接也。</p><h3 id="六三" tabindex="-1">六三 <a class="header-anchor" href="#六三" aria-label="Permalink to “六三”">​</a></h3><p>勿用娶女；見金夫，不有躬，無攸利。象曰：勿用娶女，行不順也。</p><h3 id="六四" tabindex="-1">六四 <a class="header-anchor" href="#六四" aria-label="Permalink to “六四”">​</a></h3><p>困蒙，吝。象曰：困蒙之吝，獨遠實也。</p><h3 id="六五" tabindex="-1">六五 <a class="header-anchor" href="#六五" aria-label="Permalink to “六五”">​</a></h3><p>童蒙，吉。象曰：童蒙之吉，順以巽也。</p><h3 id="上九" tabindex="-1">上九 <a class="header-anchor" href="#上九" aria-label="Permalink to “上九”">​</a></h3><p>擊蒙；不利為寇，利禦寇。象曰：利用禦寇，上下順也。</p>',19)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
